let selectedShift=null,fullDayConfirmed=false;
function currentShift(){return selectedShift||suggestedShift(state?.events||[]);}
// Làm cả ngày: chấm vào 1 lần trong Ca 1 khi hôm nay chưa chấm ca nào; 14:00 máy chủ tự chuyển sang Ca 2, về chấm ra 1 lần.
function fullDayBlock(now=Date.now()){const events=state?.events||[],today=localDay(now),hour=new Date(now+7*3600000).getUTCHours();if(completedPairs(events).pending.some(e=>e.shift==='ot'))return 'Bạn đang mở OT. Hãy kết thúc OT trước.';if(todayFullDay())return 'Hôm nay bạn đã chọn Làm cả ngày rồi. Về thì bấm chấm ra 1 lần.';if(events.some(e=>e.work_date===today&&SHIFTS.some(s=>s.id===e.shift)))return 'Hôm nay bạn đã chấm công ca làm rồi. Cả ngày chỉ chọn ở lần chấm vào đầu tiên trong ngày.';if(hour<9)return 'Chưa đến giờ. Cả ngày chọn được từ 9:00 đến trước 14:00.';if(hour>=14)return 'Đã qua 14:00. Cả ngày chỉ chọn được từ 9:00 đến trước 14:00, ở lần chấm vào đầu tiên trong ngày. Bây giờ hãy chọn Ca 2.';return '';}
const todayFullDay=()=>state?.fullDay&&state.fullDay.work_date===localDay(Date.now())?state.fullDay:null;
function actionFor(shift){if(shift!=='full_day')return shiftAction(state.events,shift);const block=fullDayBlock();if(block)throw new Error(block);return 'in';}
function currentAction(){try{return actionFor(currentShift());}catch{return null;}}
const preferredView=()=>window.matchMedia('(max-width: 800px)').matches?'attendance':'overview';
const app=document.querySelector('#app');// Giữ mục đang xem trên địa chỉ (#tasks, #bookings…) để F5 hoặc link Telegram mở đúng mục.
const PAGES=['overview','attendance','tasks','availability','rules','roster','payroll','bookings','advances','eventlog','employees','studio'];
const hashView=()=>{const page=location.hash.slice(1);return PAGES.includes(page)?page:null;};
