// Menu gộp: mỗi nhóm là một mục, các trang con hiện thành tab ở đầu trang. Hash vẫn giữ id trang con (#availability…) để link cũ mở đúng.
const navGroups=()=>{const staff=state.user.role==='employee';return [{id:'schedule',icon:'calendar',label:'Lịch',pages:[['bookings','Lịch chụp'],...(staff?[]:[['roster','Lịch làm việc']]),['availability','Đăng ký ca']]},{id:'money',icon:'wallet',label:'Công & lương',pages:[['payroll',staff?'Bảng công':'Bảng lương'],['advances','Ứng lương']]},{id:'studioinfo',icon:'book',label:'Studio',pages:[['eventlog','Event log'],['rules','Luật Studio']]}];};
const lastInGroup={};
const groupOf=page=>navGroups().find(g=>g.pages.some(([id])=>id===page));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=(t,options)=>new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',...options}).format(new Date(t));
const time=t=>t?date(t,{hour:'2-digit',minute:'2-digit'}):'—';
const day=t=>date(t,{day:'2-digit',month:'2-digit',year:'numeric'});
// Mở app sẽ nạp sẵn mọi trang (10–20 yêu cầu). Hosting giới hạn số kết nối MySQL nên mỗi máy chỉ chạy tối đa 3 GET cùng lúc, phần còn lại xếp hàng; POST (chấm công, lưu) đi ngay.
const API_GET_SLOTS=3,apiQueue=[];let apiActive=0;
async function apiSlot(task){if(apiActive<API_GET_SLOTS)apiActive++;else await new Promise(go=>apiQueue.push(go));try{return await task();}finally{const next=apiQueue.shift();if(next)next();else apiActive--;}}
// GET gặp 503 (database hosting tạm bận) thì tự thử lại một lần; POST không thử lại để tránh ghi trùng.
async function api(path,body){const send=()=>fetch(apiUrl(path),{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Nhansu-CSRF':state?.csrf||''}:{},body:body?JSON.stringify(body):undefined});if(body)return readApiResponse(await send());return apiSlot(async()=>{let r=await send();if(r.status===503){await new Promise(done=>setTimeout(done,1200));r=await send();}return readApiResponse(r);});}
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),5000);}
function icon(name){const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',wallet:'M3 6h17v14H3z M3 6V4h14 M15 11h6v5h-6z',menu:'M4 6h16 M4 12h16 M4 18h16',arrow:'M5 12h14 M14 7l5 5-5 5',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',book:'M4 4h11a3 3 0 0 1 3 3v13H7a3 3 0 0 1-3-3z M4 17a3 3 0 0 1 3-3h11',calendar:'M3 5h18v16H3z M3 10h18 M8 3v4 M16 3v4',more:'M5 12h.01 M12 12h.01 M19 12h.01',refresh:'M21 12a9 9 0 1 1-9-9c2.52 0 4.93 1 6.74 2.74L21 8 M21 3v5h-5',check:'M9 11l3 3 8-8 M20 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87'};return `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;}
function header(){return `<header class="topbar"><a class="brand" href="${BASE}/" aria-label="Anh Gấu Studio"><img class="studio-brand-image" src="https://anhgaustudio.com/wp-content/uploads/2024/05/LOGO-AG-GOLDEN-CO-VIEN.png" alt="Logo Anh Gấu Studio" referrerpolicy="strict-origin-when-cross-origin"><span class="studio-brand-name">Anh Gấu Studio<small>CHẤM CÔNG & TÍNH LƯƠNG</small></span></a>${state?`<button class="menu-toggle" id="menu-toggle" aria-label="Mở menu" aria-expanded="false">${icon('menu')}</button><span class="page-title" id="page-title">Tổng quan</span><div class="account"><span class="role-badge">${({admin:'Admin',manager:'Quản lý',employee:'Nhân viên'})[state.user.role]}</span><button type="button" class="app-refresh" id="app-refresh" aria-label="Tải lại để cập nhật ứng dụng" title="Tải lại">${icon('refresh')}</button><button type="button" class="avatar avatar-button" data-account aria-label="Tài khoản · Đổi mật khẩu">${esc(state.user.name.charAt(0).toUpperCase())}</button><span>${esc(state.user.name)}</span><button class="quiet" id="logout">Đăng xuất</button></div>`:'<span class="top-caption">Chấm công & tính lương studio</span>'}</header>`;}
function bindBrand(){const image=document.querySelector('.studio-brand-image');if(image){const fallback=()=>{image.hidden=true;image.closest('.brand').classList.add('logo-unavailable');};image.addEventListener('error',fallback,{once:true});if(image.complete&&!image.naturalWidth)fallback();}}
function auth(setup=false){state=null;selectedShift=null;document.body.classList.remove('menu-open');document.body.classList.add('login-screen');app.innerHTML=`<main class="login-page"><section class="login-shell"><svg class="login-white-shape" viewBox="0 0 800 800" preserveAspectRatio="none" aria-hidden="true"><path fill="white" d="M0 0H690C800 105 800 220 680 320C590 395 590 455 578 550L540 800H0Z"/><path fill="none" stroke="#c5d5ed" stroke-width="1.5" stroke-dasharray="5 9" d="M570 -10C705 140 623 260 538 345C472 414 484 485 469 570L430 810"/></svg><div class="login-left"><a class="brand login-brand" href="${BASE}/" aria-label="Anh Gấu Studio"><img class="studio-brand-image" src="https://anhgaustudio.com/wp-content/uploads/2024/05/LOGO-AG-GOLDEN-CO-VIEN.png" alt="Logo Anh Gấu Studio" referrerpolicy="strict-origin-when-cross-origin"><span class="studio-brand-name">Anh Gấu Studio<small>CHẤM CÔNG & TÍNH LƯƠNG</small></span></a><div class="login-content"><span class="login-eyebrow">ANH GẤU STUDIO · HỆ THỐNG NỘI BỘ</span><h1>${setup?'Thiết lập studio':'Đăng nhập'}<span>.</span></h1><p class="login-description">${setup?'Tạo tài khoản Admin đầu tiên để bắt đầu quản lý studio.':'Tài khoản do studio cấp. Chưa có thì hỏi quản lý của bạn.'}</p><form id="auth">${setup?'<div class="login-field"><label for="token">Mã thiết lập</label><input id="token" name="token" type="password" required autocomplete="off" placeholder="Mã trong tệp nhansu-private/storage/setup-token"></div><div class="login-field"><label for="name">Họ và tên quản lý</label><input id="name" name="name" required maxlength="80" autocomplete="name" placeholder="Nhập họ và tên"></div>':''}<div class="login-field"><label for="email">Email đăng nhập</label><input id="email" name="email" type="email" required autocomplete="username" placeholder="Nhập email của bạn"><span class="login-field-icon">${icon('users')}</span></div><div class="login-field"><label for="password">Mật khẩu</label><input id="password" name="password" type="password" required ${setup?'minlength="10"':''} maxlength="128" autocomplete="${setup?'new-password':'current-password'}" placeholder="Nhập mật khẩu"><button type="button" class="password-toggle" id="password-toggle" aria-label="Hiện mật khẩu" aria-pressed="false"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div><p class="error login-error" id="auth-error" role="alert"></p><button type="submit" class="primary login-submit">${setup?'Tạo studio':'Đăng nhập'} ${icon('arrow')}</button></form><p class="login-help">${setup?'Mã thiết lập được lưu trong tệp nhansu-private/storage/setup-token trên máy chủ.':'Quên mật khẩu thì nhờ quản lý đặt lại giúp.'}</p><div class="login-security"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m12 3 8 4v6c0 5-8 8-8 8s-8-3-8-8V7l8-4Z M8 12l3 3 5-5"/></svg><div><strong>Chỉ truy cập dữ liệu được cấp quyền</strong><span>Khóa tài khoản hoặc đổi quyền sẽ thu hồi phiên cũ ngay.</span></div></div></div><div class="login-footer"><span>© ${date(Date.now(),{year:'numeric'})} Anh Gấu Studio</span><span>Tiếng Việt</span></div></div><aside class="login-right"><div class="login-clock-block"><span class="login-today">HÔM NAY</span><div class="login-time"><strong id="login-time"></strong><span id="login-seconds"></span></div><p id="login-date"></p><div class="login-clock-line"></div><p class="login-tagline">Chấm công và quản lý studio<br>trong cùng một ứng dụng.</p></div><span class="login-watermark" aria-hidden="true">AG</span></aside></section></main>`;
 bindBrand();clock();document.querySelector('#password-toggle').onclick=e=>{const field=document.querySelector('#password'),button=e.currentTarget;const show=field.type==='password';field.type=show?'text':'password';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?'Ẩn mật khẩu':'Hiện mật khẩu');};
 document.querySelector('#auth').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type="submit"]');button.disabled=true;document.querySelector('#auth-error').textContent='';try{const b=Object.fromEntries(new FormData(e.target));if(setup)await api('setup',b);await api('login',b);view=hashView()||preferredView();await refresh();}catch(error){const message=document.querySelector('#auth-error');if(message)message.textContent=error.message;}finally{button.disabled=false;}};
}
function getPosition(maxAccuracy=100){return readPosition({maxAccuracy});}
function rows(events,report=false){return groupAttendanceByDay(events).map(group=>`<tr class="attendance-day-row"><td colspan="${report?7:6}"><div class="attendance-day-heading"><strong>${esc(group.title)}</strong><span>${group.events.length} lượt chấm</span></div></td></tr>`+group.events.map(e=>`<tr>${report?`<td>${esc(e.name)}</td>`:''}<td>${day(e.time)}</td><td>${esc(ATTENDANCE_OPTIONS.find(s=>s.id===e.shift)?.name||'Dữ liệu cũ')}</td><td class="${e.type}"><span class="event-label ${e.shift==='ot'?'event-ot':e.type}">${e.shift==='ot'?'OT · ':''}${e.type==='in'?'↗ Vào':'↙ Tan ca'}</span>${e.missing?'<small class="missing-checkout">Thiếu chấm ra</small>':e.working?'<small class="working-label">Đang làm</small>':''}</td><td>${time(e.time)}</td><td>${e.source==='manual'?'Chấm công hộ':e.source==='auto'?'Cả ngày':e.distance===null?'—':e.distance+' m'}</td><td>${e.source==='auto'?`<small class="manual-note">${esc(e.reason)}</small>`:e.source==='manual'?`<span class="manual-stamp" title="${esc(e.reason)}">Chấm hộ</span><small class="manual-note">${esc(e.recorded_by_name||'Quản lý')}<br>${esc(e.reason)}</small>`:e.has_photo?`<button class="photo-button" data-photo-id="${e.id}">Xem ảnh</button>`:'Dữ liệu cũ'}</td></tr>`).join('')).join('');}
function dashboard(){document.body.classList.remove('login-screen');const events=state.events;const today=events.filter(e=>day(e.time)===day(Date.now()));const action=currentAction();const active=action==='out',isOT=currentShift()==='ot',openOT=completedPairs(events).pending.find(e=>e.shift==='ot');const entry=today.filter(e=>e.type==='in').at(-1);const exit=today.find(e=>e.type==='out');const total=completedPairs(events).pairs.filter(p=>p.entry.shift!=='ot'&&day(p.entry.time)===day(Date.now())).reduce((sum,p)=>sum+Math.max(0,p.end-p.start),0);const hours=Math.floor(total/3600000),minutes=Math.floor(total/60000)%60;
app.innerHTML=header()+`<main><div class="heading"><div><span class="eyebrow">KHÔNG GIAN LÀM VIỆC CỦA BẠN</span><h1>Xin chào, ${esc(state.user.name.split(' ').at(-1))} <span aria-hidden="true">☀</span></h1><p>Sẵn sàng cho một ngày đầy cảm hứng.</p></div><div class="date">${date(Date.now(),{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'})}</div></div><div class="layout"><section class="card attendance"><div class="card-top"><span>Chấm công hôm nay</span><span class="pill">● ${openOT?'Đang OT':active?(todayFullDay()?'Đang làm cả ngày':'Đang làm việc'):events.some(e=>e.shift===currentShift()&&e.work_date===localDay(Date.now())&&e.type==='out')?'Đã kết thúc ca':'Chưa vào ca'}</span></div><div class="clock" id="clock"></div><p class="clock-date">Giờ Việt Nam · GMT+7</p><div class="location-icon" aria-hidden="true">⌖</div><div class="location-title" id="location-title">${state.studio?'Chấm công tại studio':'Studio chưa có vị trí'}</div><p class="location-sub" id="location-sub">${state.studio?`Bạn cần ở trong bán kính ${state.studio.radius} m.<br>Vị trí chỉ được lấy khi bạn nhấn chấm công.`:'Quản lý cần cài đặt tọa độ trước khi chấm công.'}</p><label for="shift" style="text-align:left">Ca làm việc</label><select id="shift" style="width:100%;margin-bottom:14px">${SHIFTS.map(s=>`<option value="${s.id}" ${s.id===(isOT?suggestedShift([]):currentShift())?'selected':''}>${s.name} · ${s.start}:00–${s.end}:00</option>`).join('')}<option value="full_day" ${currentShift()==='full_day'?'selected':''}>Cả ngày · 9:00–19:00 (chấm 1 lần)</option></select><button class="secondary ot-mode ${isOT?'selected':''}" id="ot-mode" aria-pressed="${isOT}">${openOT?'OT đang mở · Kết thúc OT':'Chấm công OT · Sau 19:00'}</button><p class="selected-shift-label">${isOT?'Đang chọn: OT':`Đang chọn: ${currentShift()==='full_day'?'Cả ngày':esc(SHIFTS.find(s=>s.id===currentShift())?.name||'Ca làm')}`}</p><p class="hint" id="shift-status">${state.expectedShifts?.[currentShift()]?`Khách đầu tiên: ${time(state.expectedShifts[currentShift()].expected_at)}. Checkin sau ${time(state.expectedShifts[currentShift()].late_after)} mới tính muộn. `:''}${action?(isOT?'Chấm vào và chấm ra OT riêng. Hệ thống lưu giờ và ảnh để đối soát.':currentShift()==='full_day'?'<strong class="full-day-warning" style="display:block;color:#b42318">⚠ Làm cả ngày: chấm vào 1 lần bây giờ, về chấm ra 1 lần. 14:00 hệ thống tự chuyển sang Ca 2. Chỉ làm 1 ca mà chọn Cả ngày sẽ bị phạt.</strong>':active&&todayFullDay()?(currentShift()==='day_first'?`Đang làm cả ngày từ ${time(events.find(e=>e.work_date===todayFullDay().work_date&&e.shift==='day_first'&&e.type==='in')?.time)}. 14:00 tự chuyển sang Ca 2, về chấm ra 1 lần (hạn 19:30).`:'Đang làm cả ngày: về thì chấm ra 1 lần. Hạn checkout: 19:30. Sau hạn, gửi yêu cầu bổ sung công.'):`Chấm vào và chấm ra riêng cho ca đã chọn. Hạn checkout: ${currentShift()==='day_first'?'14:30':'19:30'}. Sau hạn, gửi yêu cầu bổ sung công.`):(()=>{try{actionFor(currentShift());}catch(e){return esc(e.message);}})()}</p><button class="primary" id="check" data-shift="${currentShift()}" data-action="${action||''}" data-day="${localDay(Date.now())}" ${!state.studio||!action?'disabled':''}>${isOT?(active?'Kết thúc OT':action?'Bắt đầu OT':'Chưa thể bắt đầu OT'):(active?(todayFullDay()?'Kết thúc cả ngày · Chấm ra':'Kết thúc ca · Chấm ra'):action?(currentShift()==='full_day'?'Bắt đầu cả ngày · Chấm vào':'Bắt đầu ca · Chấm vào'):'Chưa thể chấm ca này')} <span aria-hidden="true">→</span></button><div id="attendance-help" hidden role="alert"><p>Hãy bật vị trí chính xác và quyền camera trong cài đặt trang web của trình duyệt. Sau đó thử lại.</p><div class="retry-actions"><button type="button" class="secondary" id="retry-location">Lấy lại vị trí</button><button type="button" class="text-button" id="retry-check">Thử chấm lại</button></div></div><p class="hint">⌑ Dùng Wi-Fi hoặc dữ liệu di động đều được</p></section><aside class="side">${dailyTasksCard()}<section class="card"><h2>Ngày làm việc của bạn</h2><div class="summary-row"><span>↗ Giờ vào đầu tiên</span><strong>${time(entry?.time)}</strong></div><div class="summary-row"><span>↙ Giờ ra gần nhất</span><strong>${time(exit?.time)}</strong></div><div class="summary-row"><span>◷ Thời gian hôm nay</span><strong>${hours} giờ ${minutes} phút</strong></div></section><section class="card note"><h2>Nhẹ nhàng bắt đầu ngày mới ✧</h2><p>Đừng quên chấm ra khi kết thúc ca. Chúc bạn có một ngày làm việc thật hiệu quả!</p></section></aside></div>${state.user.role!=='employee'?teamReportPage():''}<section class="card history personal-history" data-page="attendance"><div class="section-head"><h2>Lịch sử chấm công của tôi</h2><input type="month" id="history-month" aria-label="Tháng lịch sử chấm công" value="${localDay(Date.now()).slice(0,7)}"></div><p class="hint">Ca thiếu chấm ra được đánh dấu để bạn kiểm tra và gửi yêu cầu bổ sung.</p><div id="personal-history" class="table-wrap"></div></section>${bookingsPage(state.user)}${advancesPage(state.user)}${eventLogPage(state.user)}${tasksPage(state.user)}${availabilityPage(state.user)}${studioRulesPage(state.user)}${state.user.role!=='employee'?rosterPage(state.user):''}${requestsPanel(state.user)}${telegramPersonalPanel()}${overtimePanel()}${payrollPanel()}${state.user.role!=='employee'?commissionPanel():''}${state.user.role!=='employee'?employeesPage()+telegramSchedulesPanel()+admin()+(state.user.role==='admin'?backupPanel()+telegramAdminPanel():'')+photoGalleryPanel():''}<footer><span>Anh Gấu Studio · Chấm công & tính lương</span><span>Vị trí chỉ được sử dụng để xác nhận chấm công</span></footer></main>`;
mountShell();bindBookings({api,user:state.user,toast});bindAdvances({api,user:state.user,toast});bindEventLog({api,user:state.user,toast});bindTasks({api,user:state.user,toast});bindAvailability({api,user:state.user,toast});bindStudioRules({api,user:state.user,toast});bindBrand();document.querySelectorAll('[data-account]').forEach(b=>b.onclick=accountDialog);clock();document.querySelector('#daily-open')?.addEventListener('click',()=>showPage('tasks'));if(state.user.role!=='employee')bindRoster({api,user:state.user,toast});bindHistory();bindTelegramPersonal({api,toast});if(state.user.role!=='employee')bindTelegramSchedules({onOpen:()=>showPage('roster')});if(state.user.role==='admin')bindTelegramAdmin({api});bindRequests({api,user:state.user,toast,onChange:refresh});if(state.user.role==='admin')bindBackups({api,toast});document.querySelector('#ot-mode').onclick=()=>{selectedShift='ot';dashboard();};document.querySelector('#shift').onchange=async e=>{const value=e.target.value;if(value==='full_day'){const block=fullDayBlock();if(block){await fullDayBlocked(block);dashboard();return;}if(!await confirmFullDay()){dashboard();return;}fullDayConfirmed=true;}else fullDayConfirmed=false;selectedShift=value;dashboard();};bindPayroll();if(state.user.role!=='employee')bindCommission();bindOvertime();bindPhotoButtons(app);document.querySelector('#logout').onclick=async()=>{try{await api('logout',{});auth();}catch(e){toast(e.message);}};document.querySelector('#app-refresh').onclick=e=>{const b=e.currentTarget;b.disabled=true;b.classList.add('spinning');location.reload();};
document.querySelector('#check').onclick=check;document.querySelector('#retry-check').onclick=check;document.querySelector('#retry-location').onclick=retryLocation;if(state.user.role!=='employee'){bindAdmin();bindTeamReport();bindPhotoGallery();bindManualAttendance();bindEmployees({api,user:state.user,esc,toast,onReauth:()=>auth(),onChange:()=>{document.querySelector('#pay-month').dispatchEvent(new Event('change'));bindCommission();loadOverview();}});}}
function clock(){const checkButton=document.querySelector('#check');if(!busy&&state&&view==='attendance'&&checkButton&&(checkButton.dataset.shift!==currentShift()||checkButton.dataset.action!==(currentAction()||'')||checkButton.dataset.day!==localDay(Date.now()))){dashboard();return;}const now=Date.now(),loginTime=document.querySelector('#login-time');if(loginTime){loginTime.textContent=date(now,{hour:'2-digit',minute:'2-digit'});document.querySelector('#login-seconds').textContent=date(now,{second:'2-digit'}).padStart(2,'0');document.querySelector('#login-date').textContent=date(now,{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'});}const el=document.querySelector('#clock');if(el)el.textContent=date(Date.now(),{hour:'2-digit',minute:'2-digit',second:'2-digit'});}setInterval(clock,1000);
// Việc hằng ngày: hiện trên màn Chấm công; ca 2 phải báo xong hết mới chấm ra được.
function dailyTasksCard(){const list=state.dailyTasks||[];if(!list.length)return '';const left=list.filter(t=>!t.done_at).length;return `<section class="card daily-today"><h2>Việc hằng ngày hôm nay</h2><p class="hint">${left?`Còn ${left}/${list.length} việc. Ca 2 phải xong hết mới chấm ra được.`:'Đã xong hết việc hôm nay ✓'}</p><ul>${list.map(t=>`<li class="${t.done_at?'done':''}"><b>${t.done_at?'✓':'!'}</b><span>${esc(t.title)}${t.require_photo?' 📷':''}</span></li>`).join('')}</ul>${left?'<button type="button" class="secondary" id="daily-open">Báo xong ở mục Việc →</button>':''}</section>`;}
// Chạm avatar: xem tài khoản, tự đổi mật khẩu (cần mật khẩu hiện tại), đăng xuất.
function accountDialog(){const d=document.createElement('dialog');d.className='workflow-dialog finance-dialog account-dialog';d.innerHTML=`<div class="dialog-heading"><h2>Tài khoản</h2><button class="dialog-close" type="button" aria-label="Đóng">×</button></div><div class="account-summary"><span class="avatar">${esc(state.user.name.charAt(0).toUpperCase())}</span><div><strong>${esc(state.user.name)}</strong><small>${({admin:'Admin',manager:'Quản lý',employee:'Nhân viên'})[state.user.role]} · ${esc(state.user.email||'')}</small></div></div><form novalidate><h3>Đổi mật khẩu</h3><label>Mật khẩu hiện tại<input name="current" type="password" autocomplete="current-password" maxlength="128" required></label><label>Mật khẩu mới<input name="next" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><label>Nhập lại mật khẩu mới<input name="again" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><label class="finance-check"><input name="show" type="checkbox"> Hiện mật khẩu</label><p class="hint">Tối thiểu 10 ký tự. Đổi xong, các thiết bị khác sẽ phải đăng nhập lại.</p><p class="form-message" role="status"></p><button class="primary">Đổi mật khẩu</button></form><button type="button" class="secondary account-logout" data-logout>Đăng xuất</button>`;document.body.append(d);
 const f=d.querySelector('form'),msg=f.querySelector('.form-message'),close=()=>d.close();d.querySelector('.dialog-close').onclick=close;d.addEventListener('close',()=>d.remove(),{once:true});
 f.show.onchange=()=>['current','next','again'].forEach(n=>f[n].type=f.show.checked?'text':'password');
 d.querySelector('[data-logout]').onclick=async()=>{try{await api('logout',{});d.close();auth();}catch(e){toast(e.message);}};
 f.onsubmit=async e=>{e.preventDefault();msg.classList.remove('error');const current=f.current.value,next=f.next.value;
  const error=!current?'Nhập mật khẩu hiện tại.':next.length<10?'Mật khẩu mới cần từ 10 ký tự.':next!==f.again.value?'Hai lần nhập mật khẩu mới chưa khớp.':next===current?'Mật khẩu mới cần khác mật khẩu hiện tại.':'';
  if(error){msg.textContent=error;msg.classList.add('error');return;}
  const button=f.querySelector('button.primary');button.disabled=true;msg.textContent='Đang lưu…';
  try{await api('me/password',{current_password:current,new_password:next});d.close();toast('Đã đổi mật khẩu. Lần sau đăng nhập bằng mật khẩu mới.');}
  catch(err){msg.textContent=err.message;msg.classList.add('error');}finally{if(button.isConnected)button.disabled=false;}};
 d.showModal();}
function dailyTasksBlocked(left){const d=document.createElement('dialog');d.className='workflow-dialog finance-dialog';d.innerHTML=`<div class="dialog-heading"><h2>Chưa chấm ra được</h2><button class="dialog-close" type="button" aria-label="Đóng">×</button></div><p>Hoàn thành việc hằng ngày trước khi chấm ra ca 2:</p><ul>${left.map(t=>`<li><strong>${esc(t.title)}</strong>${t.require_photo?' · cần chụp '+(t.require_photo>1?t.require_photo+' ':'')+'ảnh':''}</li>`).join('')}</ul><div class="dialog-actions"><button type="button" class="secondary" data-close>Để sau</button><button type="button" class="primary" data-open>Mở mục Việc</button></div>`;document.body.append(d);const close=()=>d.close();d.querySelector('.dialog-close').onclick=close;d.querySelector('[data-close]').onclick=close;d.querySelector('[data-open]').onclick=()=>{d.close();showPage('tasks');};d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();}
function fullDayBlocked(reason){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='ot-confirm-dialog';dialog.setAttribute('aria-labelledby','full-day-blocked-title');dialog.innerHTML=`<div class="ot-warning-symbol">!</div><h2 id="full-day-blocked-title">Chưa chọn được Cả ngày</h2><p>${esc(reason)}</p><p class="ot-penalty-warning">Làm cả ngày: đến trong 9:00–14:00, chưa chấm ca nào thì chọn Cả ngày và chấm vào 1 lần; về chấm ra 1 lần. Chỉ làm 1 ca mà chọn Cả ngày sẽ bị phạt.</p><div class="dialog-actions"><button type="button" class="primary" id="full-day-ok">Đã hiểu</button></div>`;document.body.append(dialog);dialog.querySelector('#full-day-ok').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();resolve();},{once:true});dialog.showModal();});}
function confirmFullDay(){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='ot-confirm-dialog';dialog.setAttribute('aria-labelledby','full-day-title');dialog.innerHTML=`<div class="ot-warning-symbol">!</div><h2 id="full-day-title">Hôm nay bạn làm cả ngày đúng không?</h2><p>Làm cả ngày là làm cả Ca 1 và Ca 2 (9:00–19:00). Bạn chỉ chấm vào 1 lần lúc đến và chấm ra 1 lần lúc về; 14:00 hệ thống tự chuyển sang Ca 2.</p><p class="ot-penalty-warning">⚠ Nếu hôm nay chỉ làm 1 ca mà chọn Cả ngày, bạn sẽ bị phạt theo quy định của studio.</p><label class="ot-confirm-ack"><input type="checkbox" id="full-day-checkbox"><span>Tôi xác nhận hôm nay làm đủ cả ngày (Ca 1 + Ca 2) và hiểu quy định trên.</span></label><div class="dialog-actions"><button type="button" class="secondary" id="full-day-cancel">Không, chọn lại ca</button><button type="button" class="primary" id="full-day-accept" disabled>Đúng, tôi làm cả ngày</button></div>`;document.body.append(dialog);const checkbox=dialog.querySelector('#full-day-checkbox'),accept=dialog.querySelector('#full-day-accept');checkbox.onchange=()=>accept.disabled=!checkbox.checked;dialog.querySelector('#full-day-cancel').onclick=()=>dialog.close('cancel');accept.onclick=()=>{if(checkbox.checked)dialog.close('confirm');};dialog.addEventListener('close',()=>{const accepted=dialog.returnValue==='confirm'&&checkbox.checked;dialog.remove();resolve(accepted);},{once:true});dialog.showModal();});}
function confirmOvertimeStart(){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='ot-confirm-dialog';dialog.setAttribute('aria-labelledby','ot-confirm-title');dialog.innerHTML=`<div class="ot-warning-symbol">!</div><h2 id="ot-confirm-title">Bạn đang thực sự làm OT?</h2><p>Chỉ bắt đầu khi bạn đang làm thêm tại studio.</p><p class="ot-penalty-warning">Chấm OT sai thực tế sẽ bị xử lý theo quy định của studio. Không chấm hộ hoặc chấm khi không làm việc.</p><label class="ot-confirm-ack"><input type="checkbox" id="ot-confirm-checkbox"><span>Tôi xác nhận đang làm OT tại studio và hiểu quy định trên.</span></label><p class="ot-confirm-note">Xác nhận xong, hệ thống vẫn kiểm tra vị trí GPS và lưu thời điểm chấm.</p><div class="dialog-actions"><button type="button" class="secondary" id="ot-cancel">Hủy</button><button type="button" class="primary" id="ot-accept" disabled>Tôi đang OT – bắt đầu</button></div>`;document.body.append(dialog);const checkbox=dialog.querySelector('#ot-confirm-checkbox'),accept=dialog.querySelector('#ot-accept');checkbox.onchange=()=>accept.disabled=!checkbox.checked;dialog.querySelector('#ot-cancel').onclick=()=>dialog.close('cancel');accept.onclick=()=>{if(checkbox.checked)dialog.close('confirm');};dialog.addEventListener('close',()=>{const accepted=dialog.returnValue==='confirm'&&checkbox.checked;dialog.remove();resolve(accepted);},{once:true});dialog.showModal();});}
async function check(){
 if(busy)return;busy=true;const button=document.querySelector('#check'),originalText=button.textContent;button.disabled=true;
 try{
 if(state.clientVersion!==ATTENDANCE_CLIENT_VERSION)throw new Error('Giao diện và máy chủ chưa cùng phiên bản. Hãy cập nhật đầy đủ mã nguồn, khởi động lại web và tải lại trang.');
 // Đang làm cả ngày mà đã qua 14:00: lấy lại trạng thái (máy chủ đã tự chuyển sang Ca 2) rồi mới chấm ra.
 const full=todayFullDay();if(full&&!full.rolled_at&&Date.now()>=Date.parse(full.work_date+'T14:00:00+07:00')){button.textContent='Đang cập nhật ca…';state=await api('me');selectedShift=null;}
 const shift=currentShift(),type=actionFor(shift);let ot_confirmed=false,full_day_confirmed=false;
 if(shift==='full_day'){full_day_confirmed=fullDayConfirmed||await confirmFullDay();if(!full_day_confirmed)return;}
 if(shift==='day_first'&&type==='out'&&todayFullDay()&&!confirm('Bạn đã chọn Làm cả ngày. Chấm ra bây giờ chỉ tính Ca 1; chỉ làm 1 ca mà chọn Cả ngày sẽ bị phạt. Vẫn chấm ra?'))return;
 if(shift==='day_second'&&type==='out'){button.textContent='Đang kiểm tra việc hằng ngày…';state.dailyTasks=(await api('me')).dailyTasks||[];const left=state.dailyTasks.filter(t=>!t.done_at);if(left.length){dailyTasksBlocked(left);return;}}
 if(shift==='ot'&&type==='in'){button.textContent='Đang xác nhận OT…';ot_confirmed=await confirmOvertimeStart();if(!ot_confirmed)return;}
 button.textContent='Đang chụp ảnh xác minh…';const photo=await captureAttendancePhoto();if(!photo)return;if(jpegDataBytes(photo)>PHOTO_TARGET_BYTES)throw new Error('Ảnh chưa được nén đúng. Hãy tải lại trang rồi chụp lại.');button.textContent='Đang xác định vị trí…';const position=await getPosition(Math.min(100,state.studio?.radius||100));const result=await api('attendance',{type,shift,position,ot_confirmed,full_day_confirmed,photo});selectedShift=null;fullDayConfirmed=false;await refresh();showAttendanceSuccess({...result,shift:result.shift==='full_day'?'day_first':result.shift,photo});if(result.shift==='full_day')toast('Đã chấm vào làm cả ngày. 14:00 tự chuyển sang Ca 2; về chấm ra 1 lần.');
 }catch(error){const title=document.querySelector('#location-title'),sub=document.querySelector('#location-sub');if(title)title.textContent='Chưa thể chấm công';if(sub)sub.textContent=error.message;document.querySelector('#attendance-help').hidden=false;}
 finally{busy=false;if(button.isConnected){button.disabled=false;button.textContent=originalText;}}
}
function admin(){const s=state.studio;return `<section class="card admin"><h2>Quản lý studio</h2><p>Thiết lập địa chỉ và phạm vi chấm công của studio.</p><div class="admin-grid"><form id="settings"><h3>Vị trí chấm công</h3><p>Chọn địa chỉ rồi đặt ghim chính xác tại studio. Bán kính từ 20–1.000 m.</p>${locationPicker(s,esc)}<button type="button" class="secondary" id="locate">⌖ Lấy vị trí hiện tại</button><details class="coordinate-details"><summary>Tọa độ nâng cao (tự cập nhật theo ghim)</summary><div class="fields"><div><label for="latitude">Vĩ độ</label><input id="latitude" name="latitude" type="number" step="any" min="-90" max="90" value="${s?.latitude??''}"></div><div><label for="longitude">Kinh độ</label><input id="longitude" name="longitude" type="number" step="any" min="-180" max="180" value="${s?.longitude??''}"></div></div></details><label for="radius">Bán kính (mét)</label><input id="radius" name="radius" type="number" min="20" max="1000" required value="${s?.radius??100}"><button class="primary">Lưu vị trí studio</button><p class="form-message" role="status"></p></form></div></section>`;}
function bindAdmin(){bindLocationPicker({api,getPosition,toast,studio:state.studio});
for(const [id,path] of [['settings','settings']])document.querySelector('#'+id).onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('.primary');button.disabled=true;try{let b=Object.fromEntries(new FormData(e.target));if(id==='settings'){if(b.latitude===''||b.longitude==='')throw new Error('Chọn địa chỉ và xác nhận ghim studio trước khi lưu.');for(const key of ['latitude','longitude','radius'])b[key]=Number(b[key]);}await api(path,b);if(id==='settings'){await refresh();toast('Đã lưu vị trí studio.');}else{e.target.reset();e.target.querySelector('.form-message').textContent='Đã tạo tài khoản nhân viên.';}}catch(error){e.target.querySelector('.form-message').textContent=error.message;}finally{button.disabled=false;}};
}
function teamReportPage(){return `<section class="card history team-history" data-page="attendance"><div class="section-head"><div><h2>Lịch sử chấm công nhân viên</h2><p>Toàn studio · Xem các lượt vào/ra, ảnh và lượt chấm hộ của nhân viên.</p></div><button class="primary manual-start" id="manual-attendance">＋ Chấm công hộ</button></div><div class="team-history-filters"><label>Tháng<input type="month" id="report-month" value="${localDay(Date.now()).slice(0,7)}"></label><label>Nhân viên<select id="report-person"><option value="">Tất cả nhân viên</option></select></label><button class="secondary" id="report">↻ Cập nhật lịch sử</button><button class="text-button" id="csv">Xuất CSV</button></div><p id="report-status" role="status" aria-live="polite"></p><div id="report-result" class="table-wrap"></div></section>`;}
function bindTeamReport(){let events=[],version=0;const target=document.querySelector('#report-result'),filter=document.querySelector('#report-person'),status=document.querySelector('#report-status');const filtered=()=>events.filter(e=>!filter.value||e.user_id===Number(filter.value));
 function render(){const shown=filtered();status.textContent=`${shown.length} lượt chấm công · ${new Set(shown.map(e=>e.user_id)).size} nhân viên`;target.innerHTML=shown.length?`<table><thead><tr><th>NHÂN VIÊN</th><th>NGÀY</th><th>CA LÀM</th><th>HOẠT ĐỘNG</th><th>GIỜ</th><th>KHOẢNG CÁCH</th><th>ẢNH / NGUỒN CHẤM</th></tr></thead><tbody>${rows(markTeamAttendanceStatus(shown),true)}</tbody></table>`:'<div class="empty">Chưa có lượt chấm công phù hợp tháng và nhân viên đã chọn.</div>';bindPhotoButtons(target);}
 async function load(){const request=++version,button=document.querySelector('#report');button.disabled=true;document.querySelector('#csv').disabled=true;status.textContent='Đang tải lịch sử nhân viên…';target.textContent='Đang tải…';filter.disabled=true;try{const data=await api('report?month='+document.querySelector('#report-month').value);if(request!==version||!target.isConnected)return;events=data.events;const selected=filter.value,people=[...new Map(events.map(e=>[e.user_id,e.name])).entries()].sort((a,b)=>a[1].localeCompare(b[1],'vi'));filter.innerHTML='<option value="">Tất cả nhân viên</option>'+people.map(([id,name])=>`<option value="${id}">${esc(name)}</option>`).join('');filter.value=people.some(([id])=>String(id)===selected)?selected:'';render();document.querySelector('#csv').disabled=false;}catch(e){if(target.isConnected&&request===version){status.textContent='Chưa tải được lịch sử nhân viên.';target.textContent=e.message;}}finally{if(button.isConnected&&request===version){button.disabled=false;filter.disabled=false;}}}
 document.querySelector('#report').onclick=load;document.querySelector('#report-month').onchange=load;filter.onchange=render;
 document.querySelector('#csv').onclick=()=>{const selected=filtered(),cell=v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';const csv='\uFEFF'+[['Nhân viên','Email','Ngày','Ca làm','Hoạt động','Giờ','Khoảng cách (m)','Nguồn','Người chấm hộ','Lý do'],...selected.map(e=>[e.name,e.email,day(e.time),ATTENDANCE_OPTIONS.find(s=>s.id===e.shift)?.name||'Dữ liệu cũ',e.type==='in'?'Vào':'Ra',time(e.time),e.distance??'',e.source==='manual'?'Chấm hộ':e.source==='auto'?'Cả ngày (tự chuyển ca)':'Tự chấm',e.recorded_by_name||'',e.reason||''])].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='bang-cong-studio-'+document.querySelector('#report-month').value+'.csv';a.click();URL.revokeObjectURL(url);};load();}
async function refresh(){state=await api('me');dashboard();}
try{const status=await api('status');if(status.setup)auth(true);else{try{await refresh();}catch{auth();}}}catch(e){app.innerHTML=`<main class="auth card"><h1>Chưa kết nối được studio</h1><p>${esc(e.message)}</p><button onclick="location.reload()">Tải lại</button></main>`;}
function payrollPanel(){return `<section class="card history"><div class="section-head"><h2>${state.user.role==='employee'?'Bảng công của tôi':'Thống kê công & lương'}</h2><input aria-label="Tháng thống kê" id="pay-month" type="month" style="width:160px" value="${date(Date.now(),{year:'numeric'})}-${date(Date.now(),{month:'2-digit'})}"></div><p>${state.user.role==='employee'?'Theo dõi ca đã làm, ngày công, lượt OT và điểm KPI còn lại trong tháng (2.000 điểm/tháng). Từ 01/11/2026, ca không có khách được giao không tính công. Từ tháng 11/2026: đi làm đủ 28 ngày (tháng 2: 26 ngày) được thưởng chuyên cần 500.000đ; thợ chụp xem số khách đã chụp và hoa hồng dự tính.':'2 ca: 09–14h, 14–19h · Mỗi ca có công = 0,5 công · Lương theo công = lương cứng / số ngày của tháng × công. Từ 01/11/2026, ca của nhân viên không có khách được giao không tính công (vẫn hiện số ca không khách để xét thưởng). Lương cuối = lương theo công + hoa hồng nhập + hoa hồng lịch khách + thưởng chuyên cần − trừ KPI. Từ tháng 11/2026: nhân viên đi làm đủ 28 ngày (tháng 2: 26) được 500.000đ; thợ chụp có mức hoa hồng (hồ sơ nhân viên) được tính theo khách đã chụp, gói Team 349/399/699 ×1, Couple 999 ×2, 1499 ×4, 2999 ×8. Mỗi người 2.000 điểm KPI/tháng; 1 điểm bị trừ = 1.000đ, trừ vào thưởng, không trừ vào lương theo công.'}</p>${state.user.role!=='employee'?payrollControls():''}<div id="pay-result" class="table-wrap"></div><button class="text-button" id="pay-export">${state.user.role==='employee'?'Xuất bảng công CSV':'Xuất bảng lương CSV'}</button>${state.user.role!=='employee'?'<button class="text-button" id="manage-employees-link">Quản lý hồ sơ & lương cứng →</button>':''}</section>`;}
// Bộ đếm KPI mỗi tháng: điểm bị trừ và điểm còn lại trên quỹ 2000 (điểm, không phải tiền).
function kpiCells(p){const quota=p.kpi_quota??2000,used=p.kpi_deducted??0,left=p.kpi_left??quota-used,ratio=Math.max(0,Math.min(1,left/quota)),level=ratio>=.75?'good':ratio>=.5?'warn':'bad',n=v=>new Intl.NumberFormat('vi-VN').format(v);return `<td class="${used?'kpi-used':'kpi-zero'}">${used?'−'+n(used):'0'}</td><td><div class="kpi-meter ${level}"><span><b>${n(left)}</b> / ${n(quota)}</span><i style="--kpi:${(ratio*100).toFixed(1)}%"></i></div></td>`;}
// Thưởng tiến độ: thanh chuyên cần giống thanh KPI; ô khách đã chụp theo lịch khách (thợ chính + phụ).
function progressCell(p,staff){if(!p.attendance_target)return '<td>—</td>';const done=p.days??0,target=p.attendance_target,ratio=Math.max(0,Math.min(1,done/target)),reached=done>=target,vnd=new Intl.NumberFormat('vi-VN').format(p.attendance_bonus_vnd??500000)+'đ';return `<td><div class="kpi-meter ${reached?'good':'progress'}"><span>${staff?'Đã đi làm ':''}<b>${done}</b> / ${target} ngày</span><i style="--kpi:${(ratio*100).toFixed(1)}%"></i><small class="${reached?'ok':''}">${reached?'Đạt · thưởng '+vnd:'Còn '+(target-done)+' ngày · thưởng '+vnd}</small></div></td>`;}
function bookingCells(p,staff,money){if(p.booking_commission===undefined)return staff?'<td>—</td><td>—</td>':'<td>—</td>';const note=p.booking_unpriced?`<br><small class="out">${p.booking_unpriced} khách gói chưa có mức</small>`:'';return staff?`<td>${p.booking_customers}${note}</td><td><strong>${money(p.booking_commission)}</strong></td>`:`<td>${p.booking_customers} khách<br><small>${money(p.booking_commission)}</small>${note}</td>`;}
function bindPayroll(){let report=[];const money=v=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(v);const staff=state.user.role==='employee';async function load(){const el=document.querySelector('#pay-result');try{const r=await api('monthly?month='+document.querySelector('#pay-month').value);report=r.rows;const progress=report.some(p=>p.attendance_target),photo=report.some(p=>p.booking_commission!==undefined);if(!staff)await updatePayrollControls({api,user:state.user,month:r.month,report:r,onChange:load,toast});el.innerHTML=`<table class="payroll-table"><thead><tr><th>NHÂN VIÊN</th><th>NGÀY ĐI LÀM</th><th>CA HOÀN TẤT</th><th>LƯỢT / GIỜ OT</th><th>CÔNG</th><th>KPI BỊ TRỪ</th><th>KPI CÒN LẠI</th>${progress?'<th>CHUYÊN CẦN</th>':''}${photo?(staff?'<th>KHÁCH ĐÃ CHỤP</th><th>HOA HỒNG DỰ TÍNH</th>':'<th>KHÁCH ĐÃ CHỤP</th>'):''}${staff?'':'<th>LƯƠNG THEO CÔNG</th><th>HOA HỒNG NHẬP</th><th>LƯƠNG CUỐI</th>'}</tr></thead><tbody>${report.map(p=>`<tr><td>${esc(p.name)}${p.legacyShifts?'<br><small>Có ca cũ cần đối soát</small>':''}${p.incomplete?`<br><small class="out">${p.incomplete} ca thiếu chấm ra</small>`:''}</td><td>${p.days}</td><td>${p.completedShifts}${p.unbookedShifts?`<br><small class="out">${p.unbookedShifts} ca không khách · không tính công</small>`:''}</td><td>${p.otSessions} / ${p.otHours}h${p.otIncomplete?`<br><small class="out">${p.otIncomplete} OT chưa kết thúc</small>`:''}</td><td>${p.workdays}</td>${kpiCells(p)}${progress?progressCell(p,staff):''}${photo?bookingCells(p,staff,money):''}${staff?'':`<td>${money(p.base_salary)}</td><td>${money(p.commission)}</td><td><strong>${money(p.salary)}</strong></td>`}</tr>`).join('')}</tbody></table>${!staff&&r.closed?'<p class="hint">Tháng đã chốt: điểm KPI và lương cuối giữ theo lúc chốt.</p>':''}`;}catch(e){el.textContent=e.message;}}
document.querySelector('#pay-month').onchange=load;load();
document.querySelector('#pay-export').onclick=()=>{const staff=state.user.role==='employee';const cell=v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';const head=['Tháng','Nhân viên','Ngày đi làm','Ca hoàn tất','Ca không khách','Lượt OT hoàn tất','Giờ OT','OT chưa kết thúc','Công','Điểm KPI bị trừ','Điểm KPI còn lại','Mốc chuyên cần','Khách đã chụp','Hoa hồng lịch khách'];if(!staff)head.push('Thưởng chuyên cần','Lương theo công','Khách thường','Khách OT','Hoa hồng','Lương cuối VND');head.push('Ca thiếu chấm ra');const data=report.map(p=>{const row=[document.querySelector('#pay-month').value,p.name,p.days,p.completedShifts,p.unbookedShifts??0,p.otSessions,p.otHours,p.otIncomplete,p.workdays,p.kpi_deducted??0,p.kpi_left??2000,p.attendance_target??'',p.booking_customers??'',p.booking_commission??''];if(!staff)row.push(p.attendance_bonus??0,p.base_salary,p.regular_customers,p.ot_customers,p.commission,p.salary);row.push(p.incomplete);return row;});const csv='\uFEFF'+[head,...data].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=(staff?'bang-cong-':'bang-luong-')+document.querySelector('#pay-month').value+'.csv';a.click();URL.revokeObjectURL(url);};
if(state.user.role!=='employee')document.querySelector('#manage-employees-link').onclick=()=>showPage('employees');
}
function commissionPanel(){return `<details class="card history"><summary>Khách phục vụ & hoa hồng</summary><p>15.000đ/khách · Từ 19:00 đến trước 24:00: 30.000đ/khách. Quản lý ghi nhận theo thời điểm phục vụ. Khách OT cần có lượt chấm OT phù hợp thời điểm đó.</p>${state.user.role!=='employee'?`<form id="commission-form"><label for="commission-user">Nhân viên</label><select id="commission-user" name="user_id" required></select><div class="fields"><div><label for="served-at">Thời điểm phục vụ (giờ Việt Nam)</label><input id="served-at" name="served_at" type="datetime-local" required></div><div><label for="customers">Số khách</label><input id="customers" name="customers" type="number" min="1" max="1000" required value="1"></div></div><button class="primary">Ghi nhận khách</button><p class="form-message" role="status"></p></form>`:''}<div id="commission-history" class="table-wrap"></div></details>`;}
async function bindCommission(){async function load(){const {rows}=await api('commissions');document.querySelector('#commission-history').innerHTML=rows.length?`<table><thead><tr><th>NHÂN VIÊN</th><th>NGÀY / GIỜ</th><th>SỐ KHÁCH</th><th>LOẠI</th><th>HOA HỒNG</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${day(r.served_at)} ${time(r.served_at)}</td><td>${r.customers}</td><td>${r.rate===30000?'OT ×2':'Thường'}</td><td>${(r.customers*r.rate).toLocaleString('vi-VN')}đ</td></tr>`).join('')}</tbody></table>`:'<p>Chưa ghi nhận khách.</p>';}
try{await load();if(state.user.role==='employee')return;const {users}=await api('users');document.querySelector('#commission-user').innerHTML=users.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');document.querySelector('#served-at').value=new Date(Date.now()+7*3600000).toISOString().slice(0,16);let requestId=crypto.randomUUID();document.querySelector('#commission-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;const message=e.target.querySelector('.form-message');try{const b=Object.fromEntries(new FormData(e.target));await api('commissions',{id:requestId,user_id:Number(b.user_id),customers:Number(b.customers),served_at:Date.parse(b.served_at+':00+07:00')});requestId=crypto.randomUUID();message.textContent='Đã ghi nhận khách và hoa hồng.';await load();document.querySelector('#pay-month').dispatchEvent(new Event('change'));}catch(error){message.textContent=error.message;}finally{button.disabled=false;}};}catch(e){toast(e.message);}}
function studioIllustration(){return `<svg viewBox="0 0 360 200" class="studio-art" fill="none" aria-hidden="true"><circle cx="235" cy="113" r="87" fill="#d9ecfc"/><path d="M161 172V50h55v122M229 172V50h55v122" stroke="#9cc5e9" stroke-width="4"/><path d="M160 85h125M188 51v121M256 51v121" stroke="#b4d4ef" stroke-width="3"/><path d="M119 32h39l-19-16-20 16Z" fill="#34465e"/><path d="M139 0v16" stroke="#7fa2c5"/><path d="m123 34-17 103h69L155 34" fill="#f6fbff" fill-opacity=".5"/><rect x="106" y="144" width="164" height="10" rx="5" fill="#51789f"/><path d="m119 154-6 33m144-33 6 33" stroke="#779bc0" stroke-width="5"/><rect x="144" y="100" width="65" height="42" rx="5" fill="#8badd2"/><path d="m140 144 71-1" stroke="#3e668d" stroke-width="5"/><circle cx="176" cy="121" r="4" fill="white"/><path d="M249 115v29" stroke="#77917f" stroke-width="3"/><path d="M248 129c-33-11-31-35-14-27 11 5 14 27 14 27Z M250 121c25-8 32-34 14-28-10 4-14 28-14 28Z" fill="#77b5b7"/><path d="M235 138h30l-5 24h-20z" fill="#edc6ae"/><ellipse cx="185" cy="188" rx="126" ry="6" fill="#bdd9ee" opacity=".5"/></svg>`;}
function mountShell(){const main=app.querySelector('main');main.classList.add('workspace');const layout=main.querySelector('.layout');layout.dataset.page='attendance';const history=main.querySelector('.history');history.dataset.page='attendance';const payroll=main.querySelector('#pay-result').closest('section');payroll.dataset.page='payroll';const commission=main.querySelector('#commission-history');if(commission)commission.closest('details').dataset.page='payroll';const admin=main.querySelector('.admin');if(admin)admin.dataset.page='studio';main.querySelector('.heading').dataset.page='attendance';
main.insertAdjacentHTML('afterbegin',`<section data-page="overview" class="overview"><div class="overview-heading"><div><span class="eyebrow">ANH GẤU STUDIO</span><h1>Tổng quan</h1><p>${state.user.role==='employee'?'Theo dõi chấm công và các ca làm của bạn.':'Theo dõi chấm công và thu nhập, trong một không gian.'}</p></div><span class="live-tag"><i></i> Hệ thống đang hoạt động</span></div><form class="filterbar" id="overview-filter"><span class="branch">${icon('pin')} Studio của bạn</span><label for="overview-date" class="sr-only">Ngày thống kê</label><input type="date" id="overview-date" value="${localDay(Date.now())}"><button class="primary">Lọc dữ liệu</button><button class="refresh-button" type="button" id="overview-refresh" aria-label="Làm mới">↻</button></form><div id="overview-content" aria-live="polite"><p>Đang tải thống kê…</p></div></section>`);
app.insertAdjacentHTML('beforeend',`<aside class="sidebar" id="sidebar"><div class="sidebar-user"><button type="button" class="avatar avatar-button" data-account aria-label="Tài khoản · Đổi mật khẩu">${esc(state.user.name.charAt(0).toUpperCase())}</button><div><strong>${esc(state.user.name)}</strong><small>${({admin:'Admin',manager:'Quản lý',employee:'Nhân viên'})[state.user.role]}</small></div></div><div class="sidebar-label">KHÔNG GIAN LÀM VIỆC</div><nav aria-label="Chức năng chính">${(()=>{const [schedule,money,studioinfo]=navGroups(),item=(id,i,label)=>`<button class="nav-item" data-view="${id}">${icon(i)}<span>${label}</span><span class="nav-arrow">›</span></button>`,group=g=>`<button class="nav-item" data-nav-group="${g.id}">${icon(g.icon)}<span>${g.label}</span><span class="nav-arrow">›</span></button>`;return item('overview','grid','Tổng quan')+item('attendance','clock','Chấm công')+group(schedule)+item('tasks','check','Việc')+group(money)+group(studioinfo);})()}${state.user.role!=='employee'?`<button class="nav-item management-toggle" id="management-toggle" aria-expanded="false" aria-controls="management-submenu">${icon('users')}<span>Quản lý</span><span class="nav-arrow">⌄</span></button><div id="management-submenu" class="management-submenu" hidden><button class="nav-item" data-view="employees">${icon('users')}<span>Quản lý nhân viên</span></button><button class="nav-item" data-view="studio">${icon('pin')}<span>Quản lý studio</span></button></div>`:''}</nav><div class="sidebar-bottom"><button class="sidebar-logout" id="sidebar-logout" type="button">Đăng xuất</button><div class="sidebar-studio"><div class="studio-symbol">S</div><div>Anh Gấu Studio<small>${state.user.role==='employee'?'Chấm công · Ca làm · OT':'Chấm công · Lương · Hoa hồng'}</small></div></div><div class="sidebar-version"><span>ANH GẤU STUDIO</span><span>v1.3.29 · 30/10/2026</span></div></div></aside><button class="sidebar-backdrop" id="sidebar-backdrop" aria-label="Đóng menu"></button>`);
// Điện thoại: thanh điều hướng cố định ở đáy, dễ bấm bằng ngón cái; "Thêm" mở menu đầy đủ.
app.insertAdjacentHTML('beforeend',`<nav class="bottom-nav" aria-label="Điều hướng chính"><button data-view="attendance">${icon('clock')}<span>Chấm công</span></button><button data-nav-group="schedule">${icon('calendar')}<span>Lịch</span></button><button data-view="tasks">${icon('check')}<span>Việc</span></button><button data-nav-group="money">${icon('wallet')}<span>${state.user.role==='employee'?'Bảng công':'Lương'}</span></button><button id="bottom-more" aria-label="Mở thêm chức năng">${icon('more')}<span>Thêm</span></button></nav>`);
main.insertAdjacentHTML('afterbegin',navGroups().map(g=>`<div class="page-tabs" data-tabs="${g.id}" role="tablist" aria-label="${g.label}" hidden>${g.pages.map(([id,label])=>`<button type="button" role="tab" data-view="${id}">${label}</button>`).join('')}</div>`).join(''));
for(const button of document.querySelectorAll('[data-view]'))button.onclick=()=>showPage(button.dataset.view);
for(const button of document.querySelectorAll('[data-nav-group]'))button.onclick=()=>{const g=navGroups().find(x=>x.id===button.dataset.navGroup);showPage(lastInGroup[g.id]||g.pages[0][0]);};
const management=document.querySelector('#management-toggle');if(management)management.onclick=()=>{const menu=document.querySelector('#management-submenu');menu.hidden=!menu.hidden;management.setAttribute('aria-expanded',String(!menu.hidden));};
const toggle=()=>{const open=document.body.classList.toggle('menu-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(open));};document.querySelector('#menu-toggle').onclick=toggle;document.querySelector('#bottom-more').onclick=toggle;document.querySelector('#sidebar-logout').onclick=()=>document.querySelector('#logout').click();stackTables(main);document.querySelector('#sidebar-backdrop').onclick=toggle;
document.querySelector('#overview-filter').onsubmit=e=>{e.preventDefault();loadOverview();};document.querySelector('#overview-refresh').onclick=loadOverview;showPage(view);loadOverview();}
// Bảng trên điện thoại hiển thị dạng thẻ: gắn nhãn cột cho từng ô để CSS hiện "Nhãn: giá trị".
function stackTables(root){const label=()=>{for(const table of root.querySelectorAll('.table-wrap table')){const heads=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());if(!heads.length)continue;table.classList.add('stackable');for(const row of table.querySelectorAll('tbody tr'))[...row.children].forEach((cell,i)=>{if(heads[i]&&cell.dataset.label!==heads[i])cell.dataset.label=heads[i];});}};let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;label();});}).observe(root,{childList:true,subtree:true});label();}
function showPage(page){if(state.user.role==='employee'&&['studio','employees'].includes(page))page='overview';if(state.user.role==='employee'&&page==='roster')page='bookings';view=page;if(location.hash!=='#'+page)history.replaceState(null,'','#'+page);if(page==='tasks')document.querySelector('#task-refresh')?.click();if(page==='rules')document.querySelector('[data-page="rules"]')?.dispatchEvent(new Event('refresh'));if(page==='availability')document.querySelector('[data-page="availability"]')?.dispatchEvent(new Event('refresh'));if(page==='roster')document.querySelector('#roster-refresh')?.click();if(page==='attendance'){const report=document.querySelector('#report');if(report?.onclick&&!report.disabled)report.click();}const management=document.querySelector('#management-toggle');if(management){const selected=['employees','studio'].includes(page);management.classList.toggle('active',selected);if(selected){document.querySelector('#management-submenu').hidden=false;management.setAttribute('aria-expanded','true');}}document.querySelectorAll('[data-page]').forEach(el=>el.hidden=el.dataset.page!==page);document.querySelectorAll('[data-view]').forEach(el=>{const active=el.dataset.view===page;el.classList.toggle('active',active);if(el.closest('.page-tabs'))el.setAttribute('aria-selected',String(active));else el.setAttribute('aria-current',active?'page':'false');});const group=groupOf(page);if(group)lastInGroup[group.id]=page;document.querySelectorAll('.page-tabs').forEach(el=>el.hidden=el.dataset.tabs!==group?.id);document.querySelectorAll('[data-nav-group]').forEach(el=>{const active=el.dataset.navGroup===group?.id;el.classList.toggle('active',active);el.setAttribute('aria-current',active?'page':'false');});document.querySelector('#page-title').textContent=({overview:'Tổng quan',attendance:'Chấm công',payroll:state.user.role==='employee'?'Bảng công':'Bảng lương',studio:'Quản lý studio',employees:'Quản lý nhân viên',bookings:'Lịch chụp',advances:'Ứng lương',eventlog:'Event log',tasks:'Việc',availability:'Đăng ký ca',rules:'Luật Studio',roster:'Lịch làm việc'})[page];document.body.classList.remove('menu-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');if(page==='payroll')document.querySelector('#pay-result').closest('section').scrollIntoView({block:'start'});window.scrollTo(0,0);}
async function loadOverview(){const target=document.querySelector('#overview-content');try{const d=await api('dashboard?date='+document.querySelector('#overview-date').value);const total=d.payroll.reduce((n,p)=>n+(p.salary||0),0),commission=d.payroll.reduce((n,p)=>n+(p.commission||0),0),incomplete=d.payroll.reduce((n,p)=>n+p.incomplete,0),customers=d.payroll.reduce((n,p)=>n+(p.regular_customers||0)+(p.ot_customers||0),0);const cash=v=>v.toLocaleString('vi-VN')+'đ';target.innerHTML=`<div class="overview-grid"><div class="overview-left"><section class="shift-banner"><div class="banner-copy"><span class="banner-label">CHẤM CÔNG TRONG NGÀY</span><h2>Tổng ca hoàn tất</h2><strong class="banner-number">${d.completed}<small>/ ${d.people*2} ca có thể chấm</small></strong><div class="banner-bottom"><span><b>${d.people}</b> ${state.user.role==='employee'?'Tài khoản của bạn':'Tài khoản trong studio'}</span><span><b>${d.checkedIn}</b> ${state.user.role==='employee'?'Đã chấm vào hôm nay':'Người đã chấm vào hôm nay'}</span></div></div>${studioIllustration()}</section><div class="metric-grid"><section class="metric-card"><span class="metric-icon blue">${icon('clock')}</span><strong>${d.shifts[0].entries}</strong><span>Chấm vào ca 1</span><small>09:00 – 14:00</small></section><section class="metric-card"><span class="metric-icon purple">${icon('clock')}</span><strong>${d.shifts[1].entries}</strong><span>Chấm vào ca 2</span><small>14:00 – 19:00</small></section><section class="metric-card"><span class="metric-icon orange">${icon('users')}</span><strong>${state.user.role==='employee'?d.payroll.reduce((n,p)=>n+p.completedShifts,0):customers}</strong><span>${state.user.role==='employee'?'Ca hoàn tất':'Khách phục vụ'}</span><small>Trong tháng đã chọn</small></section><section class="metric-card"><span class="metric-icon rose">${icon('clock')}</span><strong>${incomplete}</strong><span>Ca thiếu chấm ra</span><small>Trong tháng đã chọn</small></section></div><section class="rules-banner"><span class="rules-symbol">✧</span><div><h2>${state.user.role==='employee'?'Rõ từng ca, đủ từng lượt.':'Rõ công, đúng lương.'}</h2><p>${state.user.role==='employee'?'Kiểm tra lịch sử vào, ra và các lượt OT.<br>Đừng quên chấm ra khi kết thúc công việc.':'Lương cứng theo công + hoa hồng khách.<br>Hoa hồng OT sau 19h được nhân đôi.'}</p><button class="text-button" id="overview-payroll">${state.user.role==='employee'?'Xem bảng công':'Xem bảng lương'} ${icon('arrow')}</button></div><span class="rules-watermark">${state.user.role==='employee'?'◷':'₫'}</span></section></div><div class="overview-right">${state.user.role!=='employee'?`<section class="salary-banner"><div><small>TỔNG LƯƠNG TẠM TÍNH</small><strong>${cash(total)}</strong><span>Tháng ${d.date.slice(5,7)}/${d.date.slice(0,4)}</span></div><div class="salary-divider"></div><div><small>TRONG ĐÓ HOA HỒNG</small><strong>${cash(commission)}</strong><span>Đã gồm hoa hồng OT ×2</span></div></section>`:''}<section class="card shift-schedule"><div class="section-head"><h2>Ca làm việc</h2><span class="pill">2 ca / ngày</span></div><p class="schedule-caption">Chấm vào và chấm ra riêng từng ca</p>${d.shifts.map((s,i)=>`<div class="schedule-row"><div class="schedule-icon ${i?'purple':'blue'}">${icon('clock')}</div><div><strong>${esc(s.name)}</strong><span>${s.start}:00 – ${s.end}:00 <i>·</i> 5 tiếng</span></div><span class="schedule-count">${s.exits} hoàn tất</span></div>`).join('')}<div class="ot-note"><span>OT</span><p>Sau 19:00 ${state.user.role!=='employee'?'<strong>30.000đ / khách</strong>':''}</p><small>${state.user.role==='employee'?'Chấm vào/ra OT riêng':'Hoa hồng thường: 15.000đ / khách'} · Đang OT: ${d.otActive} người</small></div><button class="primary check-link" id="overview-attendance">Đi đến chấm công ${icon('arrow')}</button><p class="gps-caption">${icon('pin')} Cần ở trong bán kính studio để chấm công</p></section></div></div>`;document.querySelector('#overview-attendance').onclick=()=>showPage('attendance');document.querySelector('#overview-payroll').onclick=()=>{document.querySelector('#pay-month').value=d.date.slice(0,7);document.querySelector('#pay-month').dispatchEvent(new Event('change'));showPage('payroll');};}catch(e){target.textContent=e.message;}}
function overtimePanel(){return `<section class="card overtime-history" data-page="attendance"><div class="section-head"><h2>${state.user.role==='employee'?'Lịch sử OT của tôi':'Theo dõi OT toàn studio'}</h2><input id="ot-month" type="month" aria-label="Tháng xem OT" value="${date(Date.now(),{year:'numeric'})}-${date(Date.now(),{month:'2-digit'})}" style="width:155px"></div><p class="ot-explanation">${state.user.role==='employee'?'Bắt đầu từ 19h · Chấm vào/ra và xác nhận GPS riêng.':'Bắt đầu từ 19h · Chấm vào/ra và xác nhận GPS riêng · Không tính vào công lương cứng.'}</p><div id="ot-report" class="table-wrap" role="region" aria-label="Các lượt chấm OT"></div><button class="text-button" id="ot-refresh">↻ Cập nhật lượt OT</button></section>`;}
function bindOvertime(){async function load(){const target=document.querySelector('#ot-report');try{const {sessions}=await api('overtime?month='+document.querySelector('#ot-month').value);target.innerHTML=sessions.length?`<table><thead><tr><th>NHÂN VIÊN</th><th>NGÀY BẮT ĐẦU</th><th>VÀO OT</th><th>RA OT</th><th>TRẠNG THÁI</th><th>GIỜ OT</th><th>XÁC NHẬN</th><th>ẢNH / NGUỒN CHẤM</th></tr></thead><tbody>${sessions.map(s=>`<tr><td>${esc(s.name)}</td><td>${day(s.start)}</td><td>${time(s.start)}</td><td>${s.end?`${time(s.end)}${day(s.start)!==day(s.end)?` (${day(s.end)})`:''}`:'—'}</td><td><span class="employee-status ${s.end?'inactive':'active'}">${s.end?'Đã kết thúc':'Đang OT'}</span></td><td>${s.hours===null?'Chưa chấm ra':s.hours+' giờ'}</td><td>${s.confirmed_at?'Đã xác nhận lúc '+time(s.confirmed_at):'Dữ liệu trước xác nhận'}</td><td>${s.in_source==='manual'?`<span class="manual-stamp" title="${esc(s.in_reason)}">Vào: chấm hộ · ${esc(s.in_recorded_by||'Quản lý')}</span>`:''}${s.out_source==='manual'?`<span class="manual-stamp" title="${esc(s.out_reason)}">Ra: chấm hộ · ${esc(s.out_recorded_by||'Quản lý')}</span>`:''}${s.in_photo?`<button class="photo-button" data-photo-id="${s.in_event_id}">Ảnh vào</button>`:''} ${s.out_photo?`<button class="photo-button" data-photo-id="${s.out_event_id}">Ảnh ra</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Chưa có lượt OT trong tháng này.</div>';bindPhotoButtons(target);}catch(error){target.textContent=error.message;}}document.querySelector('#ot-month').onchange=load;document.querySelector('#ot-refresh').onclick=load;load();}
function photoGalleryPanel(){return `<section class="card attendance-gallery" data-page="attendance"><div class="section-head"><div><h2>Ảnh chấm công</h2><p>Xem ảnh đã gửi của nhân viên, không cần duyệt công.</p></div><input id="photo-date" type="date" aria-label="Ngày xem ảnh chấm công" value="${localDay(Date.now())}"></div><div id="photo-gallery-status" role="status"></div><div id="photo-gallery" class="photo-gallery"></div><div class="gallery-pagination"><button class="secondary" id="photo-prev">Trang trước</button><span id="photo-page"></span><button class="secondary" id="photo-next">Trang sau</button></div></section>`;}
function bindPhotoGallery(){let page=1,request=0;const dateInput=document.querySelector('#photo-date');async function load(){const version=++request,status=document.querySelector('#photo-gallery-status');status.textContent='Đang tải ảnh chấm công…';try{const data=await api('attendance-photos?date='+dateInput.value+'&page='+page);if(version!==request)return;status.textContent=data.total?`${data.total} ảnh trong ngày`:'Chưa có ảnh chấm công trong ngày này.';const target=document.querySelector('#photo-gallery');target.innerHTML=data.photos.map(p=>`<button class="photo-gallery-card" data-photo-id="${p.id}" data-photo-caption="${esc(p.name)} · ${day(p.time)} ${time(p.time)} · ${p.type==='in'?'Vào':'Ra'} ${esc(ATTENDANCE_OPTIONS.find(s=>s.id===p.shift)?.name||'ca')}"><img loading="lazy" src="${apiUrl(`events/${p.id}/photo`)}" alt="Ảnh chấm công của ${esc(p.name)}"><span><strong>${esc(p.name)}</strong><small>${time(p.time)} · ${p.type==='in'?'Vào':'Ra'} ${esc(ATTENDANCE_OPTIONS.find(s=>s.id===p.shift)?.name||'ca')}</small></span></button>`).join('');bindPhotoButtons(target);document.querySelector('#photo-prev').disabled=page<=1;document.querySelector('#photo-next').disabled=page*60>=data.total;document.querySelector('#photo-page').textContent=`Trang ${page} / ${Math.max(1,Math.ceil(data.total/60))}`;}catch(error){if(version===request)status.textContent=error.message;}}dateInput.onchange=()=>{page=1;load();};document.querySelector('#photo-prev').onclick=()=>{if(page>1){page--;load();}};document.querySelector('#photo-next').onclick=()=>{page++;load();};load();}
function bindManualAttendance(){document.querySelector('#manual-attendance').onclick=async()=>{const button=document.querySelector('#manual-attendance');button.disabled=true;try{const {users}=await api('users');const available=users.filter(u=>state.user.role==='admin'||u.role==='employee');if(!available.length){toast('Chưa có nhân viên đang làm việc để chấm hộ.');return;}const dialog=document.createElement('dialog');dialog.className='manual-attendance-dialog';dialog.setAttribute('aria-labelledby','manual-attendance-title');dialog.innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">NGOẠI LỆ CHẤM CÔNG</span><h2 id="manual-attendance-title">Chấm công hộ nhân viên</h2></div><button type="button" class="dialog-close" aria-label="Đóng chấm công hộ">×</button></div><form id="manual-attendance-form"><p>Chỉ sử dụng khi nhân viên có lý do bất khả kháng. Hệ thống lưu tên bạn, thời điểm thao tác và lý do; không xác nhận GPS/camera thay nhân viên.</p><label for="manual-user">Nhân viên</label><select id="manual-user" name="user_id" required>${available.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select><label for="manual-mode">Cách chấm</label><select id="manual-mode" name="mode"><option value="shift">Cả ca · ghi luôn giờ vào và giờ ra</option><option value="single">Một lượt · chỉ vào hoặc chỉ ra, OT</option></select><div data-mode="shift"><div class="fields"><div><label for="manual-day">Ngày</label><input id="manual-day" name="day" type="date" value="${localDay(Date.now())}" max="${localDay(Date.now())}"></div><div><label for="manual-ca">Ca</label><select id="manual-ca" name="ca">${SHIFTS.filter(s=>s.id!=='ot').map(s=>`<option value="${s.id}">${s.name} · ${s.start}–${s.end}h</option>`).join('')}</select></div></div><div class="fields"><div><label for="manual-in">Giờ vào</label><input id="manual-in" name="in" type="time"></div><div><label for="manual-out">Giờ ra</label><input id="manual-out" name="out" type="time"></div></div></div><div data-mode="single" hidden><div class="fields"><div><label for="manual-shift">Ca / OT</label><select id="manual-shift" name="shift">${ATTENDANCE_OPTIONS.map(s=>`<option value="${s.id}">${s.id==='ot'?'OT sau 19h':s.name+' · '+s.start+'–'+s.end+'h'}</option>`).join('')}</select></div><div><label for="manual-type">Loại lượt chấm</label><select id="manual-type" name="type"><option value="in">Chấm vào</option><option value="out">Chấm ra</option></select></div></div><label for="manual-time">Ngày giờ làm việc (giờ Việt Nam)</label><input id="manual-time" name="time" type="datetime-local" required value="${new Date(Date.now()+7*3600000).toISOString().slice(0,16)}" max="${new Date(Date.now()+7*3600000).toISOString().slice(0,16)}"></div><label for="manual-reason">Lý do chấm hộ *</label><textarea id="manual-reason" name="reason" rows="3" minlength="10" maxlength="500" required placeholder="VD: Làm việc ngoài studio theo phân công, không thể đến điểm danh…"></textarea><label class="ot-confirm-ack" id="manual-ot-warning" hidden><input id="manual-ot-confirm" type="checkbox"><span>Tôi xác nhận nhân viên thực sự làm OT. Chấm sai sẽ bị xử lý theo quy định studio.</span></label><p class="error" id="manual-error" role="alert"></p><div class="dialog-actions"><button type="button" class="secondary" id="manual-cancel">Hủy</button><button class="primary" type="submit">Ghi nhận chấm hộ</button></div></form>`;document.body.append(dialog);const form=dialog.querySelector('form'),checkbox=dialog.querySelector('#manual-ot-confirm');const single=()=>form.elements.mode.value==='single';function toggle(){for(const box of dialog.querySelectorAll('[data-mode]')){box.hidden=box.dataset.mode!==form.elements.mode.value;for(const input of box.querySelectorAll('input,select'))input.required=!box.hidden&&input.type!=='checkbox';}const show=single()&&form.elements.shift.value==='ot'&&form.elements.type.value==='in';dialog.querySelector('#manual-ot-warning').hidden=!show;checkbox.required=show;checkbox.checked=false;}function caTimes(){const ca=SHIFTS.find(s=>s.id===form.elements.ca.value);const pad=h=>String(h).padStart(2,'0')+':00';form.elements.in.value=pad(ca.start);form.elements.out.value=pad(ca.end);}form.elements.ca.onchange=caTimes;caTimes();form.elements.mode.onchange=toggle;form.elements.shift.onchange=toggle;form.elements.type.onchange=toggle;dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.querySelector('#manual-cancel').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const b=Object.fromEntries(new FormData(form));if(single())await api('attendance/manual',{user_id:Number(b.user_id),shift:b.shift,type:b.type,time:Date.parse(b.time+':00+07:00'),reason:b.reason,ot_confirmed:checkbox.checked});else await api('attendance/manual-shift',{user_id:Number(b.user_id),shift:b.ca,in_time:Date.parse(`${b.day}T${b.in}:00+07:00`),out_time:Date.parse(`${b.day}T${b.out}:00+07:00`),reason:b.reason});dialog.close();await refresh();toast(single()?'Đã ghi nhận chấm công hộ và lưu lý do.':'Đã chấm hộ cả ca (vào + ra) và lưu lý do.');}catch(error){dialog.querySelector('#manual-error').textContent=error.message;}finally{submit.disabled=false;}};toggle();dialog.showModal();}catch(error){toast(error.message);}finally{if(button.isConnected)button.disabled=false;}};}

async function retryLocation(){const button=document.querySelector('#retry-location');button.disabled=true;try{document.querySelector('#location-sub').textContent='Đang lấy lại vị trí chính xác…';const p=await getPosition(Math.min(100,state.studio?.radius||100));document.querySelector('#location-sub').textContent=`Đã lấy vị trí, độ chính xác ±${Math.round(p.accuracy)} m. Nhấn thử chấm lại để chụp ảnh và gửi.`;}catch(e){document.querySelector('#location-sub').textContent=e.message;}finally{button.disabled=false;}}
function bindHistory(){let version=0;async function load(){const request=++version,target=document.querySelector('#personal-history');target.textContent='Đang tải lịch sử…';try{const {events}=await api('history?month='+document.querySelector('#history-month').value);if(request!==version||!target.isConnected)return;target.innerHTML=events.length?`<table><thead><tr><th>NGÀY</th><th>CA LÀM</th><th>HOẠT ĐỘNG</th><th>THỜI GIAN</th><th>KHOẢNG CÁCH</th><th>ẢNH / NGUỒN CHẤM</th></tr></thead><tbody>${rows(markAttendanceStatus(events))}</tbody></table>`:'<div class="empty">Chưa có lượt chấm công trong tháng này.</div>';bindPhotoButtons(target);}catch(e){if(target.isConnected)target.textContent=e.message;}}document.querySelector('#history-month').onchange=load;load();}
